package curryfarts.legacy;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.net.URLDecoder;
import java.util.*;
import java.util.concurrent.atomic.*;

/** Real protocol-shaped fixtures, synthetic credentials only; no Minecraft instance or network. */
public final class TokenImporterTest {
    static final String ACCESS="eyJhbGciOiJub25lIn0.eyJleHAiOjE5MDAwMDAwMDB9.c3ludGhldGlj";
    static final String PROFILE="{\"name\":\"VerifiedQA\",\"id\":\"12345678123412341234123456789abc\"}";
    static int checks;
    public static void main(String[]args)throws Exception{parse();files();auth();batch();System.out.println("TokenImporterTest: "+checks+" checks passed (synthetic tokens, no network).");}
    static void parse(){List<TokenImportBatch.Entry>list=TokenImportBatch.parse("\uFEFF# comment\r\n=== ignored\r\n\r\n"+ACCESS+"\r\nName:"+ACCESS+"\nM.Crefresh\nName:M.Crefresh\nemail:password | MCTOKEN: "+ACCESS+" | REFRESHTOKEN: M.Cpreferred\nMCTOKEN: "+ACCESS);check(list.size()==6,"input forms/comments/BOM");check(list.get(0).line==4,"line numbers");check(list.get(1).token.equals(ACCESS),"supplied name discarded");check(list.get(4).token.equals("M.Cpreferred"),"refresh preferred over session");check(!list.toString().contains(ACCESS),"entry diagnostics redact");for(TokenImportBatch.Entry e:TokenImportBatch.parse("REFRESHTOKEN:\nname:password\nrandom text\nM.Cbad token")){check(e.kind==TokenImportBatch.Kind.INVALID&&e.token.isEmpty(),"invalid input not retained");}expectIllegal(()->TokenImportBatch.parse(new String(new char[1048577])));StringBuilder many=new StringBuilder();for(int i=0;i<1001;i++)many.append("invalid\n");expectIllegal(()->TokenImportBatch.parse(many.toString()));}
    static void files()throws Exception{Path dir=Files.createTempDirectory("token-import-java8-");Path file=dir.resolve("input.txt");try{Files.write(file,("\uFEFF"+ACCESS).getBytes(StandardCharsets.UTF_8));check(TokenImportBatch.parse(TokenImportBatch.readFile(file)).get(0).token.equals(ACCESS),"UTF8 TXT round trip");Files.write(file,new byte[]{(byte)0xc3,0x28});expectIo(()->TokenImportBatch.readFile(file));Files.write(file,new byte[1048577]);expectIo(()->TokenImportBatch.readFile(file));expectIo(()->TokenImportBatch.readFile(dir));expectIo(()->TokenImportBatch.readFile(dir.resolve("missing.txt")));}finally{Files.deleteIfExists(file);Files.delete(dir);}}
    static void auth()throws Exception{List<TokenRefresher.Request> requests=new ArrayList<TokenRefresher.Request>();TokenRefresher.Transport success=r->{requests.add(r);switch(r.endpoint){case MICROSOFT:check(URLDecoder.decode(r.body,"UTF-8").contains("client_id=00000000402b5328"),"Live client matches upstream");check(URLDecoder.decode(r.body,"UTF-8").contains("refresh_token=M.Csynthetic+&token"),"refresh form encoded");return reply(200,"{\"access_token\":\"msa.synthetic\",\"refresh_token\":\"M.Crotated\"}");case XBOX:check(r.body.contains("t=msa.synthetic"),"Live Xbox ticket prefix");return reply(200,"{\"Token\":\"xbox.synthetic\",\"DisplayClaims\":{\"xui\":[{\"uhs\":\"111\"}]}}");case XSTS:return reply(200,"{\"Token\":\"xsts.synthetic\",\"DisplayClaims\":{\"xui\":[{\"uhs\":\"222\"}]}}");case LOGIN:check(r.body.contains("XBL3.0 x=222;xsts.synthetic"),"XSTS hash preferred");return reply(200,"{\"access_token\":\"mc.synthetic\",\"expires_in\":86400}");case ENTITLEMENTS:check(r.bearer.equals("mc.synthetic"),"entitlement bearer");return reply(200,"{\"items\":[]}");default:return reply(200,PROFILE);}};TokenRefresher.Verified v=new TokenRefresher(success).refresh("M.Csynthetic+&token");check(requests.size()==6,"complete refresh protocol");check(v.username.equals("VerifiedQA")&&v.uuid.equals("12345678-1234-1234-1234-123456789abc"),"server identity authoritative");check(v.refreshToken.equals("M.Crotated"),"refresh rotation retained");check(v.expiresAt>System.currentTimeMillis()+86000000L,"session expiry returned");for(TokenRefresher.Request r:requests){check(r.endpoint.url.startsWith("https://"),"fixed HTTPS target");check(!r.toString().contains("synthetic"),"request diagnostics safe");}check(!v.toString().contains("M.Crotated")&&!reply(200,ACCESS).toString().contains(ACCESS),"result diagnostics safe");
        TokenRefresher session=new TokenRefresher(r->{check(r.endpoint==TokenRefresher.Endpoint.PROFILE,"raw session only validates profile");return reply(200,PROFILE);});check(session.validateSession(ACCESS).refreshToken.isEmpty(),"session never refreshed");expect(TokenRefresher.FailureKind.INVALID,()->new TokenRefresher(r->reply(401,"")).validateSession(ACCESS));String expired="eyJhbGciOiJub25lIn0."+Base64.getUrlEncoder().withoutPadding().encodeToString("{\"exp\":1}".getBytes(StandardCharsets.UTF_8))+".synthetic";expect(TokenRefresher.FailureKind.EXPIRED,()->new TokenRefresher(r->reply(401,"")).validateSession(expired));expect(TokenRefresher.FailureKind.RATE_LIMITED,()->new TokenRefresher(r->reply(429,ACCESS)).refresh("M.Csynthetic"));expect(TokenRefresher.FailureKind.NETWORK,()->new TokenRefresher(r->reply(503,ACCESS)).refresh("M.Csynthetic"));expect(TokenRefresher.FailureKind.UNSUPPORTED,()->new TokenRefresher(r->reply(307,ACCESS)).refresh("M.Csynthetic"));expect(TokenRefresher.FailureKind.NETWORK,()->new TokenRefresher(r->{throw new IOException(ACCESS);}).refresh("M.Csynthetic"));expect(TokenRefresher.FailureKind.NETWORK,()->new TokenRefresher(r->reply(200,"not json")).refresh("M.Csynthetic"));expect(TokenRefresher.FailureKind.NETWORK,()->new TokenRefresher(r->reply(200,"{}")).validateSession(ACCESS));expect(TokenRefresher.FailureKind.INVALID,()->new TokenRefresher(r->{throw new AssertionError();}).validateSession("bad\r\nheader"));
        String[]codes={"invalid_grant","expired_grant","slow_down","temporarily_unavailable","consent_required"};TokenRefresher.FailureKind[]kinds={TokenRefresher.FailureKind.INVALID,TokenRefresher.FailureKind.EXPIRED,TokenRefresher.FailureKind.RATE_LIMITED,TokenRefresher.FailureKind.NETWORK,TokenRefresher.FailureKind.UNSUPPORTED};for(int i=0;i<codes.length;i++){final String code=codes[i];expect(kinds[i],()->new TokenRefresher(r->reply(400,"{\"error\":\""+code+"\",\"error_description\":\""+ACCESS+"\"}")).refresh("M.Csynthetic"));}
        Thread.currentThread().interrupt();try{session.validateSession(ACCESS);throw new AssertionError("cancel");}catch(InterruptedException expected){check(true,"interruption blocks request");}finally{Thread.interrupted();}}
    static void batch(){AtomicInteger calls=new AtomicInteger();TokenImportBatch.Authenticator auth=new TokenImportBatch.Authenticator(){public TokenRefresher.Verified validate(String t){calls.incrementAndGet();return verified();}public TokenRefresher.Verified refresh(String t){calls.incrementAndGet();return verified();}};List<TokenImportBatch.Progress>updates=new ArrayList<TokenImportBatch.Progress>();TokenImportBatch.Progress done=TokenImportBatch.run(ACCESS+"\nName:"+ACCESS+"\ninvalid",auth,(v,c)->TokenImportBatch.Stored.IMPORTED,()->false,updates::add);check(done.imported==1&&done.duplicates==1&&done.invalid==1,"batch import and duplicate accounting");check(calls.get()==1,"duplicate token avoids HTTP");check(updates.get(0).processed==0&&updates.get(updates.size()-1)==done,"initial/final progress");AtomicBoolean cancel=new AtomicBoolean(true);TokenImportBatch.Progress cancelled=TokenImportBatch.run(ACCESS,auth,(v,c)->{throw new AssertionError();},cancel::get,p->{});check(cancelled.cancelled&&cancelled.processed==0,"pre-cancellation");TokenImportBatch.Authenticator cancelDuring=new TokenImportBatch.Authenticator(){public TokenRefresher.Verified validate(String t){cancel.set(true);return verified();}public TokenRefresher.Verified refresh(String t){return verified();}};cancel.set(false);check(TokenImportBatch.run(ACCESS,cancelDuring,(v,c)->{throw new AssertionError();},cancel::get,p->{}).cancelled,"late validation cannot save after cancel");TokenImportBatch.Authenticator rate=new TokenImportBatch.Authenticator(){public TokenRefresher.Verified validate(String t)throws TokenRefresher.Failure{throw new TokenRefresher.Failure(TokenRefresher.FailureKind.RATE_LIMITED);}public TokenRefresher.Verified refresh(String t){return verified();}};TokenImportBatch.Progress limited=TokenImportBatch.run(ACCESS+"\n"+ACCESS,rate,(v,c)->{throw new AssertionError();},()->false,p->{});check(limited.failed==1&&limited.processed==1,"rate limit stops batch");TokenImportBatch.Progress failed=TokenImportBatch.run(ACCESS,auth,(v,c)->{throw new IllegalStateException(ACCESS);},()->false,p->{});check(failed.failed==1&&!failed.results.get(0).message.contains(ACCESS),"save errors fixed and redacted");}
    static TokenRefresher.Verified verified(){return new TokenRefresher.Verified("VerifiedQA","12345678-1234-1234-1234-123456789abc",ACCESS,"",1900000000000L);}
    static TokenRefresher.Reply reply(int status,String text){return new TokenRefresher.Reply(status,text);}
    interface Action{void run()throws Exception;}
    static void expect(TokenRefresher.FailureKind kind,Action action)throws Exception{try{action.run();throw new AssertionError("expected "+kind);}catch(TokenRefresher.Failure error){check(error.kind==kind,"failure category "+kind);check(error.getCause()==null&&!error.getMessage().contains(ACCESS),"error text safe");}}
    static void expectIllegal(Runnable action){try{action.run();throw new AssertionError();}catch(IllegalArgumentException expected){checks++;}}
    static void expectIo(Action action)throws Exception{try{action.run();throw new AssertionError();}catch(IOException expected){checks++;}}
    static void check(boolean value,String message){if(!value)throw new AssertionError(message);checks++;}
}
